using System;
using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "HauntedChalkOmenData", menuName = "Data/Battle/Omens System/Omen Data/Moonie/HauntedChalkOmenData")]
public class HauntedChalkOmenData : OmenData
{
	private Action<List<MoonieOmensHandler.DiceInstanceEnhanced>> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(List<MoonieOmensHandler.DiceInstanceEnhanced> diceInstancesEnhanced)
		{
			for (int i = 0; i < diceInstancesEnhanced.Count; i++)
			{
				if (diceInstancesEnhanced[i].DiceInstance.DiceOwnerEnum == DiceOwnerEnum.ENEMY && ((diceInstancesEnhanced[i].DiceInstance.ActionFace.BattleAction is PurifyAction && diceInstancesEnhanced[i].OriginalActionValue == 1) || (diceInstancesEnhanced[i].DiceInstance.ActionFace.SecondBattleAction is PurifyAction && diceInstancesEnhanced[i].OriginalSecondActionValue == 1)))
				{
					omenInstance.EnqueueOmenFeedbackAndPlay();
					diceInstancesEnhanced[i].DiceInstance.ActionOwner.GetComponent<CorruptedAnimalCorruptionStats>().Purify(ActionValue, null);
				}
			}
		};
		ReferenceSingleton<MoonieOmensHandler>.Instance.OnPlayerEnhanceOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MoonieOmensHandler>.Instance.OnPlayerEnhanceOmenActions.Remove(omenAction);
	}
}
